page.goto("https://www.worldometers.info/world-population/population-by-country/");
return page.evaluate(() => {
const rows=[...document.querySelectorAll("table tbody tr")].map(r=>[...r.cells].map(c=>c.textContent.trim()));
const h=[...document.querySelectorAll("table thead th")].map(c=>c.textContent.trim());
const pi=h.findIndex(x=>x.startsWith("Population")), fi=h.findIndex(x=>x.startsWith("Fert"));
const top=rows.map(r=>({n:r[1],p:+r[pi].replace(/,/g,''),f:r[fi]})).sort((a,b)=>b.p-a.p).slice(0,10);
return {h,top};
});
